<?php get_header(); ?><main id="primary" class="container content-area content-area--narrow"><?php while ( have_posts() ) : the_post(); ?><article <?php post_class( 'entry' ); ?>><header class="page-heading"><p class="eyebrow"><?php echo esc_html( get_the_date() ); ?></p><h1><?php the_title(); ?></h1></header><?php if ( has_post_thumbnail() ) : ?><div class="entry-featured"><?php the_post_thumbnail( 'large' ); ?></div><?php endif; ?><div class="entry-content"><?php the_content(); wp_link_pages(); ?></div><?php if ( comments_open() || get_comments_number() ) { comments_template(); } ?></article><?php endwhile; ?></main><?php get_footer(); ?>
